import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.DQe9aj1R.js";const _=JSON.parse('{"title":"インストール","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1789803897000}'),n={name:"guide/installation.md"};function r(l,e,d,s,p,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h1><p>Unity の版は 6000.6.2f1 に固定しています。別の版ではモジュールの名前や開き方が違います。</p><h2 id="用意するもの" tabindex="-1">用意するもの <a class="header-anchor" href="#用意するもの" aria-label="Permalink to &quot;用意するもの&quot;">​</a></h2><ol><li><a href="https://unity3d.com/jp/get-unity/download" target="_blank" rel="noreferrer">Unity Hub</a> を入れ、6000.6.2f1 を選びます。</li><li>実機へ出す予定があるなら、Android Build Support（SDK &amp; NDK Tools と OpenJDK を含む）と iOS Build Support、日本語言語パックも付けます。Android Build Support だけだと SDK が入らないことがあります。</li><li>このリポジトリのフォルダを、Unity Hub の「リストに追加」から登録します。</li><li>プロジェクトを開き、<code>Assets/Game.unity</code> を表示した状態で再生ボタンを押します。</li></ol><p>青空の画像と日本語、右上の経過秒数が出れば、エディタ側の準備は足りています。再生で何も出ないときは、開いているシーンが <code>Assets/Game.unity</code> かを見てください。メニューの <code>GameCanvas/エディタ設定/起動時に Game.unity を開く</code> を入れておくと、次から迷いにくくなります。</p><p>Windows での導入は、このリポジトリでは確認していません。Android 実機ではポインターとキーの押下・解放を確認しています。iOSシミュレータではタップ、ドラッグ、ホームへ移ったあとの復帰と、そのあとの新しいドラッグ、日本語表示を確認しています。iOSの複数指と、接触中のキャンセルは未確認です。</p><p>実機への書き出しは、メニューの <code>GameCanvas/アプリをビルドする</code> と <a href="https://github.com/sfc-sdp/SDP-Textbook" target="_blank" rel="noreferrer">講義テキスト</a> を見てください。</p>',7)])])}const m=a(n,[["render",r]]);export{_ as __pageData,m as default};
